import React, { useState } from 'react';
import { MapContainer, TileLayer, CircleMarker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import EventCard from './EventCard';

export default function MapView({ events }) {
  const [selectedId, setSelectedId] = useState(null);

  return (
    <div style={{ display: 'flex', height: 'calc(100vh - 64px)', gap: 0 }}>
      {/* Map */}
      <div style={{ flex: 1, position: 'relative' }}>
        <MapContainer
          center={[20, 10]}
          zoom={2}
          style={{ width: '100%', height: '100%' }}
          scrollWheelZoom={true}
        >
          <TileLayer
            attribution='&copy; <a href="https://carto.com/">CARTO</a>'
            url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png"
          />
          {events.map((ev) => (
            <CircleMarker
              key={ev.id}
              center={[ev.lat, ev.lng]}
              radius={selectedId === ev.id ? 10 : 7}
              pathOptions={{
                fillColor: selectedId === ev.id ? '#185FA5' : '#378ADD',
                fillOpacity: 1,
                color: '#fff',
                weight: 2,
              }}
              eventHandlers={{
                click: () => setSelectedId(ev.id === selectedId ? null : ev.id),
              }}
            >
              <Popup closeButton={false}>
                <div style={{ padding: '8px 4px', minWidth: 160 }}>
                  <div style={{ fontWeight: 600, fontSize: 14 }}>{ev.name}</div>
                  <div style={{ fontSize: 12, color: '#666', marginTop: 2 }}>{ev.city} · {ev.date}</div>
                  <a
                    href={ev.website}
                    target="_blank"
                    rel="noreferrer"
                    style={{ fontSize: 12, display: 'block', marginTop: 6, color: '#185FA5' }}
                  >
                    Voir le site →
                  </a>
                </div>
              </Popup>
            </CircleMarker>
          ))}
        </MapContainer>
      </div>

      {/* Side panel */}
      <div style={{
        width: 320,
        background: 'var(--surface)',
        borderLeft: '1px solid var(--border)',
        overflowY: 'auto',
        display: 'flex',
        flexDirection: 'column',
      }}>
        <div style={{ padding: '16px 20px', borderBottom: '1px solid var(--border)' }}>
          <div style={{ fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.08em', color: 'var(--text-muted)' }}>
            {events.length} événements
          </div>
        </div>

        {!selectedId && (
          <div style={{
            flex: 1, display: 'flex', flexDirection: 'column',
            alignItems: 'center', justifyContent: 'center',
            color: 'var(--text-muted)', fontSize: 13, padding: 24, textAlign: 'center', gap: 8
          }}>
            <span style={{ fontSize: 28 }}>🗺️</span>
            Cliquez sur un marqueur pour voir les détails de l'événement
          </div>
        )}

        {selectedId && (() => {
          const ev = events.find(e => e.id === selectedId);
          return (
            <div style={{ padding: 16 }}>
              <button
                onClick={() => setSelectedId(null)}
                style={{
                  background: 'none', border: 'none', cursor: 'pointer',
                  fontSize: 12, color: 'var(--text-muted)', marginBottom: 12,
                  padding: 0, display: 'flex', alignItems: 'center', gap: 4
                }}
              >
                ← Fermer
              </button>
              <EventCard event={ev} isSelected={true} />
              <a
                href={ev.website}
                target="_blank"
                rel="noreferrer"
                style={{
                  display: 'block', marginTop: 12, textAlign: 'center',
                  background: 'var(--accent)', color: '#fff',
                  padding: '10px 16px', borderRadius: 'var(--radius-md)',
                  fontSize: 13, fontWeight: 500, textDecoration: 'none'
                }}
              >
                Voir le site officiel →
              </a>
            </div>
          );
        })()}
      </div>
    </div>
  );
}
